'use client'

import { useEffect, useMemo, useRef, useState } from 'react'
import Link from 'next/link'
import { usePathname, useRouter, useSearchParams } from 'next/navigation'
import { ChevronDown, ChevronRight, LogOut, Moon, Palette, Search, Settings, Sun, SunMoon, User } from 'lucide-react'
import { getBreadcrumbs } from '@/lib/breadcrumbs'
import { useTheme } from 'next-themes'
import { createClient } from '@/lib/supabase/client'
import {
  SidebarInset,
  SidebarTrigger,
} from '@/components/ui/sidebar'
import { Separator } from '@/components/ui/separator'
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from '@/components/ui/breadcrumb'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuPortal,
  DropdownMenuSeparator,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Button } from '@/components/ui/button'
import { CommandPalette } from '@/components/shared/CommandPalette'
import { MobileNav } from '@/components/shared/MobileNav'
import { BottomNav } from '@/components/shared/BottomNav'
import { ThemeToggle } from '@/components/shared/ThemeToggle'
import { CommissionPulsePill } from '@/components/app/sidebar/CommissionPulsePill'
import { QuickAddClientModal } from '@/components/clients/QuickAddClientModal'
import { AppointmentCreateDrawer } from '@/components/appointments/AppointmentCreateDrawer'
import { StudioSwitcher } from '@/components/shared/StudioSwitcher'
import { LocationSwitcher } from '@/components/shared/LocationSwitcher'
import { useQueryClient } from '@tanstack/react-query'
import type { NavRole } from '@/components/app/sidebar/nav-config'
import type { PlanTier } from '@/lib/billing/feature-gate'
import { useFocusOnRouteChange } from '@/hooks/useFocusOnRouteChange'
import type { StudioMembership } from '@/lib/context/active-studio'
import type { LocationRow } from '@/lib/context/active-location'
import type { DynamicBadgeCounts } from '@/components/app/sidebar/SidebarNavGroup'

interface AppHeaderProps {
  studioName: string
  studioSlug?: string
  userName: string
  userEmail?: string
  userAvatarUrl?: string | null
  role: NavRole
  plan?: PlanTier
  /** S15: all studio memberships — single item = no switcher rendered */
  allMemberships: StudioMembership[]
  /** S15: active studio id */
  currentStudioId: string
  /** S15: active location id (null = all locations) */
  currentLocationId: string | null
  /** S15: all locations for active studio — <2 = no switcher rendered */
  allLocations: LocationRow[]
  permissionKeys: string[]
  /** S17: dynamic badge counts for MobileNav */
  dynamicBadges?: DynamicBadgeCounts
  /** S22: month-to-date commission total cents — null hides pill */
  mtdCommissionCents?: number | null
  /** S22: whether the current user can view commissions */
  canViewCommissions?: boolean
  /**
   * Dynamic breadcrumb labels keyed by pathname prefix.
   * Populated server-side by `lib/breadcrumbs/resolve.ts`.
   * Example: `{ '/clients/abc123': 'Jane Doe' }`.
   */
  dynamicLabels?: Record<string, string>
  children: React.ReactNode
}

// S18: /dashboard is the canonical home route. Label map drives the fallback
// breadcrumb pageLabel when the pure pathname parser can't infer a label.
const ROUTE_LABELS: Record<string, string> = {
  '/dashboard': 'Dashboard',
  '/inbox': 'Inbox',
  '/messages': 'Messages',
  '/portfolio': 'Flash & Portfolio',
  '/calendar': 'Calendar',
  '/appointments': 'Appointments',
  '/appointments/new': 'New Appointment',
  '/clients': 'Clients',
  '/artists': 'Team',
  '/inventory': 'Inventory',
  '/payments': 'Payments',
  '/consent-forms': 'Forms',
  '/reports': 'Analytics',
  '/ai-design': 'AI',
  '/locations': 'Locations',
  '/marketing': 'Marketing',
  '/settings': 'Settings',
  '/settings/studio/profile': 'Studio Profile',
  '/settings/studio/branding': 'Branding',
  '/settings/studio/services': 'Services',
  '/settings/studio/policies': 'Booking Policies',
  '/settings/studio/booking-page': 'Booking Page',
  '/settings/studio/ink-registry': 'Ink Registry',
  '/settings/team/members': 'Team & Members',
  '/settings/subscription/billing': 'Billing & Plan',
  '/settings/subscription/usage': 'Usage',
  '/settings/integrations': 'Integrations',
  '/settings/account/profile': 'My Profile',
  '/settings/account/advanced': 'Advanced',
  '/admin': 'Admin',
}

function getPageLabel(pathname: string): string {
  if (ROUTE_LABELS[pathname]) return ROUTE_LABELS[pathname]
  const match = Object.keys(ROUTE_LABELS)
    .filter((k) => pathname.startsWith(k) && k !== '/')
    .sort((a, b) => b.length - a.length)[0]
  return ROUTE_LABELS[match ?? ''] ?? 'InkOS'
}

function getInitials(name: string): string {
  return name
    .split(' ')
    .slice(0, 2)
    .map((n) => n[0])
    .join('')
    .toUpperCase()
}

const G_CHORD_TIMEOUT_MS = 500

// G-chord map (press "g" then letter for fast-jump): d→dashboard, i→inbox, c→calendar, etc.
const G_CHORD_MAP: Record<string, string> = {
  d: '/dashboard',
  i: '/inbox',
  c: '/calendar',
  l: '/clients',
  a: '/artists',
  s: '/settings/studio/profile',
  p: '/payments',
  b: '/settings/subscription/billing',
  n: '/inventory',
  f: '/consent-forms',
  m: '/messages',
}

export function AppHeader({
  studioName,
  studioSlug,
  userName,
  userEmail,
  userAvatarUrl,
  role,
  plan = 'solo',
  allMemberships,
  currentStudioId,
  currentLocationId,
  allLocations,
  permissionKeys,
  dynamicBadges,
  mtdCommissionCents,
  canViewCommissions,
  dynamicLabels,
  children,
}: AppHeaderProps) {
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const router = useRouter()
  const queryClient = useQueryClient()

  // S23 — breadcrumb trail: Dashboard > Section > Page (tab-aware).
  // dynamicLabels is populated server-side by resolveDynamicLabels() so detail
  // routes render entity names (e.g. "Jane Doe") instead of UUIDs.
  const breadcrumbs = useMemo(
    () => getBreadcrumbs(pathname, searchParams?.get('tab') ?? null, dynamicLabels ?? {}),
    [pathname, searchParams, dynamicLabels],
  )

  useFocusOnRouteChange()
  const { resolvedTheme, setTheme } = useTheme()
  const supabase = createClient()

  const [paletteOpen, setPaletteOpen] = useState(false)
  const [addClientOpen, setAddClientOpen] = useState(false)
  const [newAppointmentOpen, setNewAppointmentOpen] = useState(false)
  const [mobileNavOpen, setMobileNavOpen] = useState(false)

  const lastKeyRef = useRef<string>('')
  const lastKeyTimeRef = useRef<number>(0)

  // Legacy label fallback — kept for now in case the page tab title ever uses it.
  void getPageLabel

  useEffect(() => {
    function handleKeyDown(e: KeyboardEvent) {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault()
        setPaletteOpen(true)
        return
      }
      if ((e.metaKey || e.ctrlKey) && e.shiftKey && e.key === 'l') {
        e.preventDefault()
        setTheme(resolvedTheme === 'dark' ? 'light' : 'dark')
        return
      }
      if (e.metaKey || e.ctrlKey || e.altKey) return
      const target = e.target as HTMLElement
      if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA') return
      if (target.isContentEditable) return

      const key = e.key.toLowerCase()
      const now = Date.now()

      if (
        lastKeyRef.current === 'g' &&
        now - lastKeyTimeRef.current < G_CHORD_TIMEOUT_MS &&
        G_CHORD_MAP[key]
      ) {
        e.preventDefault()
        router.push(G_CHORD_MAP[key])
        lastKeyRef.current = ''
        return
      }

      if (key === 'n') {
        router.push('/appointments/new')
      }

      lastKeyRef.current = key
      lastKeyTimeRef.current = now
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [router, resolvedTheme, setTheme])

  async function handleSignOut() {
    await supabase.auth.signOut()
    router.push('/login')
    router.refresh()
  }

  return (
    <SidebarInset className="flex flex-col">
      <header className="relative sticky top-0 z-40 flex h-14 shrink-0 items-center gap-3 border-b border-border/60 bg-[var(--color-header-bg)] px-4 after:pointer-events-none after:absolute after:inset-x-0 after:bottom-0 after:h-px after:bg-[linear-gradient(to_right,_oklch(58%_0.16_35/_0.5),_transparent_55%)]">
        <div className="flex min-w-0 flex-1 items-center gap-2">
          <MobileNav
            userName={userName}
            userEmail={userEmail ?? ''}
            userAvatarUrl={userAvatarUrl}
            studioName={studioName}
            {...(studioSlug !== undefined ? { studioSlug } : {})}
            role={role}
            plan={plan}
            locationCount={allLocations.length}
            permissionKeys={permissionKeys}
            {...(dynamicBadges !== undefined ? { dynamicBadges } : {})}
            onSignOut={handleSignOut}
            open={mobileNavOpen}
            onOpenChange={setMobileNavOpen}
            allMemberships={allMemberships}
            currentStudioId={currentStudioId}
            currentLocationId={currentLocationId}
            allLocations={allLocations}
          />
          <SidebarTrigger className="hidden h-8 w-8 shrink-0 text-muted-foreground/70 hover:text-foreground md:flex" />
          <Separator orientation="vertical" className="h-4 bg-border/50" />

          {/* S18 — Breadcrumb: Dashboard > Section > Page (tab-aware).
              Studio + Location switchers moved to the right side of the header
              as supplementary pills; they are workspace identity, not nav. */}
          <Breadcrumb className="min-w-0">
            <BreadcrumbList className="gap-1.5 text-[13px]">
              {/* Desktop: full trail */}
              {breadcrumbs.map((crumb, i) => {
                const isLast = i === breadcrumbs.length - 1
                return (
                  <span key={`${crumb.label}-${i}`} className="hidden items-center gap-1.5 md:flex">
                    {i > 0 && (
                      <BreadcrumbSeparator>
                        <ChevronRight className="h-3.5 w-3.5 text-muted-foreground/40" aria-hidden="true" />
                      </BreadcrumbSeparator>
                    )}
                    <BreadcrumbItem>
                      {isLast || !crumb.href ? (
                        <BreadcrumbPage className="truncate font-semibold tracking-tight text-foreground">
                          {crumb.label}
                        </BreadcrumbPage>
                      ) : (
                        <BreadcrumbLink
                          render={
                            <Link
                              href={crumb.href}
                              className="truncate text-muted-foreground/80 transition-colors hover:text-foreground"
                            />
                          }
                        >
                          {crumb.label}
                        </BreadcrumbLink>
                      )}
                    </BreadcrumbItem>
                  </span>
                )
              })}

              {/* Mobile: only the last (current page) crumb to save space */}
              <BreadcrumbItem className="flex md:hidden">
                <BreadcrumbPage className="truncate font-semibold text-foreground">
                  {breadcrumbs[breadcrumbs.length - 1]?.label ?? 'Dashboard'}
                </BreadcrumbPage>
              </BreadcrumbItem>
            </BreadcrumbList>
          </Breadcrumb>

          <div aria-live="polite" aria-atomic="true" className="sr-only" id="studio-switch-announcement" />
        </div>

        <div className="flex shrink-0 items-center gap-1.5">
          {/* S18 — Workspace identity pills moved out of breadcrumb and to the
              header-right. Only render when there's something to switch. */}
          {allMemberships.length >= 2 && (
            <div className="hidden md:flex">
              <StudioSwitcher
                currentStudioId={currentStudioId}
                allMemberships={allMemberships}
              />
            </div>
          )}
          {allLocations.length >= 2 && (
            <div className="hidden md:flex">
              <LocationSwitcher
                currentLocationId={currentLocationId}
                allLocations={allLocations}
                role={role as unknown as Parameters<typeof LocationSwitcher>[0]['role']}
              />
            </div>
          )}

          {/* S22: Commission Pulse Pill — desktop only, role-gated */}
          {canViewCommissions && (
            <CommissionPulsePill totalCents={mtdCommissionCents ?? null} />
          )}

          <Button
            variant="ghost"
            className="flex h-11 w-11 items-center justify-center md:hidden"
            aria-label="Search"
            onClick={() => setPaletteOpen(true)}
          >
            <Search className="size-4" aria-hidden="true" />
          </Button>

          <button
            type="button"
            aria-label="Open command palette"
            onClick={() => setPaletteOpen(true)}
            className="hidden h-8 cursor-pointer items-center gap-2 rounded-lg border border-border/60 bg-muted/30 px-2.5 text-[12px] font-medium text-muted-foreground/80 transition-all hover:border-border hover:bg-muted/60 hover:text-foreground md:flex"
          >
            <span>Search</span>
            <kbd className="pointer-events-none flex h-5 items-center gap-0.5 rounded border border-border/60 bg-background px-1.5 text-[10px] font-mono text-muted-foreground/60">
              <span>⌘</span><span>K</span>
            </kbd>
          </button>

          <ThemeToggle variant="icon" />

          <DropdownMenu>
            <DropdownMenuTrigger
              render={
                <button
                  type="button"
                  aria-label="User menu"
                  className="flex h-9 cursor-pointer items-center gap-1.5 rounded-lg px-1 text-sm outline-none transition-all hover:bg-muted/50 focus-visible:ring-2 focus-visible:ring-ring"
                />
              }
            >
              <Avatar className="h-7 w-7 rounded-full ring-1 ring-border/60">
                {userAvatarUrl && (
                  <AvatarImage src={userAvatarUrl} alt={userName} />
                )}
                <AvatarFallback className="rounded-full bg-foreground text-[11px] font-semibold text-background">
                  {getInitials(userName)}
                </AvatarFallback>
              </Avatar>
              <ChevronDown className="h-3.5 w-3.5 text-muted-foreground/50 transition-transform data-[popup-open]:rotate-180" />
            </DropdownMenuTrigger>

            <DropdownMenuContent
              side="bottom"
              align="end"
              className="w-56 rounded-xl border-border/60 p-1.5 shadow-[var(--shadow-lift)]"
              sideOffset={8}
            >
              <DropdownMenuLabel className="flex items-center gap-2.5 rounded-md px-2 py-2">
                <Avatar className="h-9 w-9 rounded-full ring-1 ring-border/60">
                  {userAvatarUrl && (
                    <AvatarImage src={userAvatarUrl} alt={userName} />
                  )}
                  <AvatarFallback className="rounded-full bg-foreground text-[11px] font-semibold text-background">
                    {getInitials(userName)}
                  </AvatarFallback>
                </Avatar>
                <div className="grid min-w-0 flex-1">
                  <span className="truncate text-[13px] font-semibold leading-tight">{userName}</span>
                  <span className="truncate text-[11px] font-normal text-muted-foreground">{userEmail}</span>
                </div>
              </DropdownMenuLabel>
              <DropdownMenuSeparator className="my-1" />

              <DropdownMenuItem
                onClick={() => router.push('/settings/account/profile')}
                className="gap-2.5 rounded-md px-2 py-1.5 text-[13px]"
              >
                <User className="h-4 w-4 text-muted-foreground/70" aria-hidden="true" />
                Profile
              </DropdownMenuItem>

              <DropdownMenuItem
                onClick={() => router.push('/settings')}
                className="gap-2.5 rounded-md px-2 py-1.5 text-[13px]"
              >
                <Settings className="h-4 w-4 text-muted-foreground/70" aria-hidden="true" />
                Settings
              </DropdownMenuItem>

              <DropdownMenuSub>
                <DropdownMenuSubTrigger className="gap-2.5 rounded-md px-2 py-1.5 text-[13px]">
                  <Palette className="h-4 w-4 text-muted-foreground/70" aria-hidden="true" />
                  Theme
                </DropdownMenuSubTrigger>
                <DropdownMenuPortal>
                  <DropdownMenuSubContent className="rounded-xl border-border/60 p-1.5 shadow-[var(--shadow-lift)]">
                    <DropdownMenuItem onClick={() => setTheme('light')} className="gap-2.5 rounded-md px-2 py-1.5 text-[13px]">
                      <Sun className="h-4 w-4 text-muted-foreground/70" aria-hidden="true" />
                      Light
                    </DropdownMenuItem>
                    <DropdownMenuItem onClick={() => setTheme('dark')} className="gap-2.5 rounded-md px-2 py-1.5 text-[13px]">
                      <Moon className="h-4 w-4 text-muted-foreground/70" aria-hidden="true" />
                      Dark
                    </DropdownMenuItem>
                    <DropdownMenuItem onClick={() => setTheme('system')} className="gap-2.5 rounded-md px-2 py-1.5 text-[13px]">
                      <SunMoon className="h-4 w-4 text-muted-foreground/70" aria-hidden="true" />
                      System
                    </DropdownMenuItem>
                  </DropdownMenuSubContent>
                </DropdownMenuPortal>
              </DropdownMenuSub>

              <DropdownMenuSeparator className="my-1" />

              <DropdownMenuItem
                onClick={handleSignOut}
                className="gap-2.5 rounded-md px-2 py-1.5 text-[13px] text-destructive focus:bg-destructive/10 focus:text-destructive"
              >
                <LogOut className="h-4 w-4" aria-hidden="true" />
                Sign out
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </header>

      <CommandPalette
        open={paletteOpen}
        onOpenChange={setPaletteOpen}
        onCreateClient={() => setAddClientOpen(true)}
      />
      <QuickAddClientModal open={addClientOpen} onOpenChange={setAddClientOpen} />

      <main
        id="main-content"
        tabIndex={-1}
        className="flex-1 overflow-auto bg-[var(--color-page-bg,var(--color-background))] pb-16 outline-none md:pb-0"
      >
        {children}
      </main>

      <BottomNav
        onNew={() => setNewAppointmentOpen(true)}
        onMoreOpen={() => setMobileNavOpen(true)}
      />

      <AppointmentCreateDrawer
        open={newAppointmentOpen}
        onOpenChange={setNewAppointmentOpen}
        editingId={null}
        onSuccess={() => {
          setNewAppointmentOpen(false)
          void queryClient.invalidateQueries({ queryKey: ['bookings'] })
        }}
      />
    </SidebarInset>
  )
}

'use client'

import { useMemo } from 'react'
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarHeader,
} from '@/components/ui/sidebar'
import { SidebarNavGroup } from '@/components/app/sidebar/SidebarNavGroup'
import type { DynamicBadgeCounts } from '@/components/app/sidebar/SidebarNavGroup'
import { APP_NAV, type NavRole } from '@/components/app/sidebar/nav-config'
import { BookingLinkWidget } from '@/components/app/sidebar/BookingLinkWidget'
import { SidebarFavorites } from '@/components/app/sidebar/SidebarFavorites'
import { SidebarUserFooter } from '@/components/app/sidebar/SidebarUserFooter'
import { StudioSwitcher } from '@/components/shared/StudioSwitcher'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { StudioMembership } from '@/lib/context/active-studio'
import type { UserPinnedItem } from '@/lib/pinned-items/pinned'

interface AppSidebarProps {
  plan: PlanTier
  studioName: string
  studioLogoUrl?: string | null
  studioSlug: string
  role: NavRole
  locationCount: number
  /** Serialized from server — Set<string> → JSON array → passed as prop */
  permissionKeys?: string[]
  /** Dynamic badge counts from server (inbox, calendar, clients, inventory) */
  dynamicBadges?: DynamicBadgeCounts
  /** S15: all studio memberships — single item = no switcher rendered */
  allMemberships: StudioMembership[]
  /** S15: active studio id */
  currentStudioId: string
  /** User info for footer */
  userName: string
  userEmail: string
  userAvatarUrl?: string | null
  /** S22: pinned items for Favorites section */
  pinnedItems?: UserPinnedItem[]
}

export function AppSidebar({
  plan,
  studioName,
  studioLogoUrl,
  studioSlug,
  role,
  locationCount,
  permissionKeys = [],
  dynamicBadges = {},
  allMemberships,
  currentStudioId,
  userName,
  userEmail,
  userAvatarUrl,
  pinnedItems = [],
}: AppSidebarProps) {
  const permissions = useMemo(() => new Set(permissionKeys), [permissionKeys])

  const navGroups = useMemo(() => {
    return APP_NAV
      .filter((group) => !(group.condition === 'multi-location' && locationCount <= 1))
      .map((group) => ({
        ...group,
        items: group.items.filter((item) => {
          if (!item.requiredRoles.includes(role)) return false
          if (item.requiredPermission && !permissions.has(item.requiredPermission)) return false
          return true
        }),
      }))
      .filter((group) => group.items.length > 0)
  }, [role, locationCount, permissions])

  return (
    <Sidebar
      collapsible="icon"
      className={[
        'border-r border-sidebar-border',
        // Rust edge accent — barely-visible 1px gradient stripe on the right seam.
        // Fades in/out vertically so it reads as a brand signature, not a hard line.
        'relative after:pointer-events-none after:absolute after:right-0 after:top-0 after:h-full after:w-px',
        'after:bg-[linear-gradient(to_bottom,transparent_0%,oklch(58%_0.16_35/_0.12)_40%,oklch(58%_0.16_35/_0.12)_60%,transparent_100%)]',
      ].join(' ')}
    >
      {/* ── Brand header with ⌘K hint ─────────────────────────── */}
      <SidebarHeader className="border-b border-sidebar-border/60 px-3 py-2.5">
        <div className="flex items-center gap-2 group-data-[collapsible=icon]:justify-center">
          {studioLogoUrl ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={studioLogoUrl}
              alt={studioName}
              className="h-8 w-8 shrink-0 rounded-md object-cover"
            />
          ) : (
            /* InkOS brand mark — italic `i` in Onyx tile per brand book */
            <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-md bg-foreground text-background">
              <span className="font-serif-italic text-xl leading-none">i</span>
            </div>
          )}
          <div className="flex min-w-0 flex-col leading-tight group-data-[collapsible=icon]:hidden">
            <span className="truncate text-[13px] font-bold tracking-tight text-sidebar-foreground">
              InkOS
            </span>
            <span className="truncate text-[10px] font-medium uppercase tracking-[0.08em] text-stone-brand">
              Studio OS
            </span>
          </div>
          {/* ⌘K hint pill */}
          <button
            type="button"
            aria-label="Open command palette (⌘K)"
            onClick={() => {
              // Dispatch synthetic ⌘K to trigger AppHeader's palette handler
              window.dispatchEvent(
                new KeyboardEvent('keydown', { key: 'k', metaKey: true, bubbles: true })
              )
            }}
            className="ml-auto flex h-5 shrink-0 items-center gap-0.5 rounded border border-border/50 bg-muted/30 px-1.5 text-[10px] font-mono text-muted-foreground/60 transition-colors hover:border-border hover:bg-muted/60 hover:text-muted-foreground group-data-[collapsible=icon]:hidden"
          >
            <span>⌘</span><span>K</span>
          </button>
        </div>

        {/* Studio switcher row */}
        <div className="mt-2 group-data-[collapsible=icon]:hidden">
          {allMemberships.length >= 2 ? (
            <StudioSwitcher
              currentStudioId={currentStudioId}
              allMemberships={allMemberships}
            />
          ) : (
            <div className="flex h-8 items-center gap-2 rounded-lg border border-border/40 bg-muted/20 px-2">
              <span className="truncate text-[13px] font-medium text-sidebar-foreground/80">
                {studioName}
              </span>
            </div>
          )}
        </div>

        {/* Booking link widget */}
        <BookingLinkWidget studioSlug={studioSlug} className="mt-1.5 mx-0" />
      </SidebarHeader>

      {/* ── Nav groups ────────────────────────────────────────── */}
      <SidebarContent className="gap-0 px-2 py-3">
        {navGroups.map((group, idx) => (
          <SidebarNavGroup
            key={group.label ?? '_unlabeled'}
            group={group}
            plan={plan}
            isFirst={idx === 0}
            dynamicBadges={dynamicBadges}
          />
        ))}

        {/* S22: Favorites */}
        <SidebarFavorites pinnedItems={pinnedItems} />
      </SidebarContent>

      {/* ── User footer ───────────────────────────────────────── */}
      <SidebarFooter className="p-0">
        <SidebarUserFooter
          userName={userName}
          userEmail={userEmail}
          userAvatarUrl={userAvatarUrl}
          role={role}
        />
      </SidebarFooter>
    </Sidebar>
  )
}

import { redirect } from 'next/navigation'
import { cookies, headers } from 'next/headers'
import { createClient } from '@/lib/supabase/server'
import { resolveDynamicLabels } from '@/lib/breadcrumbs/resolve'
import { SidebarProvider } from '@/components/ui/sidebar'
import { AppSidebar } from '@/components/app/sidebar/AppSidebar'
import { AppHeader } from '@/components/app/sidebar/AppHeader'
import { PermissionsProvider } from '@/lib/team/permissions-context'
import { getUserPermissions } from '@/lib/team/permissions'
import { StudioParamSync } from '@/components/shared/StudioParamSync'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import { getActiveLocation } from '@/lib/context/active-location'
import { fetchUserPins } from '@/lib/pinned-items/pinned'
import { getMtdCommissionTotal } from '@/lib/commissions/get-mtd-summary'
import type { DynamicBadgeCounts } from '@/components/app/sidebar/SidebarNavGroup'

interface AppLayoutProps {
  children: React.ReactNode
}

export default async function AppLayout({ children }: AppLayoutProps) {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) {
    redirect('/login')
  }

  // S15: resolve active studio via cookie (replaces .limit(1).single() pattern)
  let activeStudio: Awaited<ReturnType<typeof getActiveStudio>>
  try {
    activeStudio = await getActiveStudio()
  } catch (err) {
    if (err instanceof NoStudioMembershipError) {
      redirect('/onboarding')
    }
    redirect('/onboarding')
  }

  const { studioId, studio, role, plan, allMemberships } = activeStudio

  // S15: resolve active location (depends on studioId — sequential, not Promise.all)
  const activeLocation = await getActiveLocation(studioId, role)

  // Fetch user profile + dynamic badge counts in parallel
  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString()
  const oneDayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString()
  const todayStart = new Date()
  todayStart.setHours(0, 0, 0, 0)
  const todayEnd = new Date()
  todayEnd.setHours(23, 59, 59, 999)

  // S22: resolve artist record id for artist-role MTD filter
  // artists.profile_id links to profiles.id (= user.id)
  let artistIdForMtd: string | undefined
  if (role === 'artist') {
    const { data: artistRow } = await supabase
      .from('artists')
      .select('id')
      .eq('profile_id', user.id)
      .eq('studio_id', studioId)
      .maybeSingle()
    artistIdForMtd = artistRow?.id
  }

  const [
    profileResult,
    inboxPendingRes,
    inboxConsentRes,
    inboxWaitlistRes,
    calendarTodayRes,
    clientsTotalRes,
    inventoryLowRes,
    inboxUnreadConvsRes,
  ] = await Promise.all([
    supabase
      .from('profiles')
      .select('full_name, avatar_url')
      .eq('id', user.id)
      .single(),
    // Inbox: pending bookings (status='pending')
    supabase
      .from('bookings')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId)
      .eq('status', 'pending'),
    // Inbox: consent submissions in last 7d (no reviewed_at field — approximate with signed_at)
    supabase
      .from('consent_form_submissions')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId)
      .gte('created_at', sevenDaysAgo)
      .is('soft_deleted_at', null),
    // Inbox: waitlist entries in last 24h
    supabase
      .from('waitlist_entries')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId)
      .gte('created_at', oneDayAgo),
    // Calendar: bookings scheduled today
    supabase
      .from('bookings')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId)
      .gte('scheduled_at', todayStart.toISOString())
      .lte('scheduled_at', todayEnd.toISOString()),
    // Clients: total for studio
    supabase
      .from('clients')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId),
    // Inventory: items at zero stock (proxy for low-stock alert)
    supabase
      .from('inventory_items')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId)
      .eq('is_active', true)
      .eq('current_stock', 0),

    // Inbox: unread conversation count
    supabase
      .from('conversations')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId)
      .is('archived_at', null)
      .gt('unread_count', 0),
  ])

  // S22: Pins + MTD commissions + dynamic breadcrumb labels — parallel after main badge fetches
  const canViewCommissions = role === 'owner' || role === 'admin' || role === 'artist'
  const currentPathname = (await headers()).get('x-pathname') ?? '/dashboard'
  const [pinnedItems, mtdResult, dynamicLabels] = await Promise.all([
    fetchUserPins(user.id, studioId),
    canViewCommissions
      ? getMtdCommissionTotal(supabase, studioId, artistIdForMtd ? { artistId: artistIdForMtd } : undefined)
      : Promise.resolve(null),
    resolveDynamicLabels(supabase, currentPathname),
  ])
  const mtdCommissionCents = mtdResult?.totalCents ?? null

  // Permissions
  const permissionsSet =
    studioId && user ? await getUserPermissions(studioId, user.id) : new Set<string>()
  const permissionKeys = [...permissionsSet]

  // Sidebar state from cookie
  const cookieStore = await cookies()
  const sidebarOpen = cookieStore.get('sidebar_state')?.value !== 'false'

  const profile = profileResult.data
  const userName = profile?.full_name ?? user.email?.split('@')[0] ?? 'You'
  const userEmail = user.email ?? ''
  const userAvatarUrl = profile?.avatar_url ?? null
  const studioName = studio.name
  const studioLogoUrl = studio.logo_url ?? null
  const studioSlug = studio.slug

  // Compute dynamic badge counts (graceful: null count → 0)
  const inboxCount =
    (inboxPendingRes.count ?? 0) +
    (inboxConsentRes.count ?? 0) +
    (inboxWaitlistRes.count ?? 0) +
    (inboxUnreadConvsRes.count ?? 0)

  const dynamicBadges: DynamicBadgeCounts = {
    inbox: inboxCount,
    calendar: calendarTodayRes.count ?? 0,
    clients: clientsTotalRes.count ?? 0,
    inventory: inventoryLowRes.count ?? 0,
  }

  return (
    <PermissionsProvider permissionKeys={permissionKeys}>
      {/* S15: StudioParamSync handles ?studio=X deep links — renders null */}
      <StudioParamSync currentStudioId={studioId} />
      <SidebarProvider defaultOpen={sidebarOpen} className="h-svh">
        <AppSidebar
          locationCount={activeLocation.allLocations.length}
          plan={plan}
          studioName={studioName}
          studioLogoUrl={studioLogoUrl}
          studioSlug={studioSlug}
          role={role}
          permissionKeys={permissionKeys}
          dynamicBadges={dynamicBadges}
          allMemberships={allMemberships}
          currentStudioId={studioId}
          userName={userName}
          userEmail={userEmail}
          userAvatarUrl={userAvatarUrl}
          pinnedItems={pinnedItems}
        />
        <AppHeader
          studioName={studioName}
          studioSlug={studioSlug}
          userName={userName}
          userEmail={userEmail}
          userAvatarUrl={userAvatarUrl}
          role={role}
          plan={plan}
          allMemberships={allMemberships}
          currentStudioId={studioId}
          currentLocationId={activeLocation.locationId}
          allLocations={activeLocation.allLocations}
          permissionKeys={permissionKeys}
          dynamicBadges={dynamicBadges}
          mtdCommissionCents={mtdCommissionCents}
          canViewCommissions={canViewCommissions}
          dynamicLabels={dynamicLabels}
        >
          {children}
        </AppHeader>
      </SidebarProvider>
    </PermissionsProvider>
  )
}

'use client'

import { useCallback, useEffect, useMemo, useState } from 'react'
import { usePathname, useRouter } from 'next/navigation'
import { LogOut, Menu, X } from 'lucide-react'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Button } from '@/components/ui/button'
import { ScrollArea } from '@/components/ui/scroll-area'
import { Sheet, SheetContent } from '@/components/ui/sheet'
import { cn } from '@/lib/utils'
import { APP_NAV, type NavItem, type NavRole } from '@/components/app/sidebar/nav-config'
import { PlanBadge } from '@/components/shared/PlanBadge'
import { StudioSwitcher } from '@/components/shared/StudioSwitcher'
import { LocationSwitcher } from '@/components/shared/LocationSwitcher'
import { BookingLinkWidget } from '@/components/app/sidebar/BookingLinkWidget'
import { hasFeature } from '@/lib/billing/feature-gate'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { StudioMembership } from '@/lib/context/active-studio'
import type { LocationRow } from '@/lib/context/active-location'
import type { DynamicBadgeCounts } from '@/components/app/sidebar/SidebarNavGroup'

interface MobileNavProps {
  userName: string
  userEmail: string
  userAvatarUrl: string | null | undefined
  studioName: string
  studioSlug?: string
  role: NavRole
  locationCount: number
  permissionKeys: string[]
  plan?: PlanTier
  dynamicBadges?: DynamicBadgeCounts
  onSignOut: () => void
  open?: boolean
  onOpenChange?: (open: boolean) => void
  allMemberships: StudioMembership[]
  currentStudioId: string
  currentLocationId: string | null
  allLocations: LocationRow[]
}

function getInitials(name: string): string {
  return name
    .split(' ')
    .slice(0, 2)
    .map((n) => n[0])
    .join('')
    .toUpperCase()
}

interface MobileNavItemProps {
  item: NavItem
  onNavigate: () => void
  isActive: boolean
  plan: PlanTier
  dynamicBadges: DynamicBadgeCounts
}

function MobileNavItem({ item, onNavigate, isActive, plan, dynamicBadges }: MobileNavItemProps) {
  const Icon = item.icon
  const router = useRouter()

  const isGated =
    !!item.requiredPlan &&
    !hasFeature(plan, item.featureKey ?? item.requiredPlan)

  const dynamicCount = item.dynamicBadge !== undefined ? (dynamicBadges[item.dynamicBadge] ?? 0) : 0
  const showCountBadge = item.badgeType === 'count' && dynamicCount > 0 && !isGated
  const showDotBadge = item.badgeType === 'dot' && dynamicCount > 0 && !isGated
  const showNewBadge = item.badgeType === 'new' && !isGated

  function formatCount(n: number): string {
    if (n >= 1000) return `${(n / 1000).toFixed(1)}k`
    return String(n)
  }

  function handleClick() {
    if (isGated) {
      onNavigate()
      router.push('/settings/subscription/billing')
      return
    }
    onNavigate()
    router.push(item.href)
  }

  return (
    <button
      type="button"
      className={cn(
        'flex w-full min-h-[44px] items-center gap-2.5 rounded-lg px-2.5 text-[13px] font-medium transition-colors text-left',
        isActive
          ? 'bg-accent text-accent-foreground'
          : 'text-muted-foreground hover:bg-muted/50 hover:text-foreground',
        isGated && 'opacity-60',
      )}
      onClick={handleClick}
      aria-current={isActive ? 'page' : undefined}
    >
      <Icon className="size-4 shrink-0" aria-hidden="true" />
      {item.label}

      {/* Plan badge for gated items */}
      {isGated && item.requiredPlan && item.requiredPlan !== 'solo' && (
        <PlanBadge plan={item.requiredPlan} className="ml-auto" />
      )}

      {/* Count badge */}
      {showCountBadge && (
        <span className="ml-auto inline-flex min-w-[20px] items-center justify-center rounded-full bg-muted px-1.5 py-0.5 text-[10px] font-semibold tabular-nums text-muted-foreground">
          {formatCount(dynamicCount)}
        </span>
      )}

      {/* Dot badge */}
      {showDotBadge && (
        <span className="ml-auto flex h-2 w-2 shrink-0 rounded-full bg-destructive" aria-label="Alert" />
      )}

      {/* New badge */}
      {showNewBadge && (
        <span className="ml-auto inline-flex items-center rounded-sm border border-rust/40 bg-rust-tint px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-[0.08em] text-rust">
          NEW
        </span>
      )}
    </button>
  )
}

export function MobileNav({
  userName,
  userEmail,
  userAvatarUrl,
  studioName,
  studioSlug,
  role,
  locationCount,
  permissionKeys,
  plan = 'solo',
  dynamicBadges = {},
  onSignOut,
  open: externalOpen,
  onOpenChange: externalOnOpenChange,
  allMemberships,
  currentStudioId,
  currentLocationId,
  allLocations,
}: MobileNavProps) {
  const [internalOpen, setInternalOpen] = useState(false)
  const open = externalOpen !== undefined ? externalOpen : internalOpen
  const setOpen = useCallback((v: boolean) => {
    setInternalOpen(v)
    externalOnOpenChange?.(v)
  }, [externalOnOpenChange])
  const pathname = usePathname()

  const permissions = useMemo(() => new Set(permissionKeys), [permissionKeys])
  const navGroups = useMemo(() => {
    return APP_NAV
      .filter((group) => !(group.condition === 'multi-location' && locationCount <= 1))
      .map((group) => ({
        ...group,
        items: group.items.filter((item) => {
          if (!item.requiredRoles.includes(role)) return false
          if (item.requiredPermission && !permissions.has(item.requiredPermission)) return false
          return true
        }),
      }))
      .filter((group) => group.items.length > 0)
  }, [role, locationCount, permissions])

  useEffect(() => {
    setOpen(false)
  }, [pathname, setOpen])

  const showStudioSwitcher = allMemberships.length >= 2
  const showLocationSwitcher = allLocations.length >= 2

  return (
    <>
      <Button
        variant="ghost"
        className="flex h-11 w-11 items-center justify-center md:hidden"
        aria-label="Open navigation"
        aria-expanded={open}
        aria-controls="mobile-nav-sheet"
        onClick={() => setOpen(true)}
      >
        <Menu className="size-4" aria-hidden="true" />
      </Button>

      <Sheet open={open} onOpenChange={setOpen}>
        <SheetContent
          id="mobile-nav-sheet"
          side="left"
          className="w-[280px] p-0 flex flex-col"
          showCloseButton={false}
        >
          <div className="flex items-center gap-3 border-b border-border/60 px-4 py-4">
            <Avatar className="h-9 w-9 rounded-full ring-1 ring-border/60 shrink-0">
              {userAvatarUrl && <AvatarImage src={userAvatarUrl} alt={userName} />}
              <AvatarFallback className="rounded-full bg-foreground text-[11px] font-semibold text-background">
                {getInitials(userName)}
              </AvatarFallback>
            </Avatar>
            <div className="min-w-0 flex-1">
              <p className="truncate text-[13px] font-semibold leading-tight text-foreground">{userName}</p>
              <p className="truncate text-[11px] text-muted-foreground">{studioName}</p>
              <p className="truncate text-[10px] text-muted-foreground/60">{userEmail}</p>
            </div>
            <Button
              variant="ghost"
              className="h-8 w-8 shrink-0"
              onClick={() => setOpen(false)}
              aria-label="Close navigation"
            >
              <X className="size-4" aria-hidden="true" />
            </Button>
          </div>

          {/* Booking link widget in sheet header */}
          {studioSlug && (
            <div className="border-b border-border/60 px-3 py-2">
              <BookingLinkWidget studioSlug={studioSlug} className="mx-0" />
            </div>
          )}

          {(showStudioSwitcher || showLocationSwitcher) && (
            <div className="border-b border-border/60 px-3 py-2 space-y-1">
              {showStudioSwitcher && (
                <div className="flex items-center gap-2 min-h-[44px] px-1">
                  <span className="w-16 shrink-0 text-[11px] text-muted-foreground/60">Studio</span>
                  <StudioSwitcher currentStudioId={currentStudioId} allMemberships={allMemberships} />
                </div>
              )}
              {showLocationSwitcher && (
                <div className="flex items-center gap-2 min-h-[44px] px-1">
                  <span className="w-16 shrink-0 text-[11px] text-muted-foreground/60">Location</span>
                  <LocationSwitcher currentLocationId={currentLocationId} allLocations={allLocations} role={role as unknown as Parameters<typeof LocationSwitcher>[0]['role']} />
                </div>
              )}
            </div>
          )}

          <ScrollArea className="flex-1">
            <nav className="px-2 py-3 space-y-4" aria-label="Mobile navigation">
              {navGroups.map((group) => (
                <div key={group.label ?? '_unlabeled'}>
                  {/* Skip label for unlabeled group (null label) */}
                  {group.label !== null && (
                    <p className="mb-1 px-2 text-[10px] font-semibold uppercase tracking-[0.1em] text-muted-foreground/50">
                      {group.label}
                    </p>
                  )}
                  <div className="space-y-0.5">
                    {group.items.map((item) => (
                      <MobileNavItem
                        key={item.href}
                        item={item}
                        isActive={
                          item.href === '/dashboard'
                            ? pathname === item.href
                            : pathname.startsWith(item.href.split('?')[0] ?? item.href)
                        }
                        onNavigate={() => setOpen(false)}
                        plan={plan}
                        dynamicBadges={dynamicBadges}
                      />
                    ))}
                  </div>
                </div>
              ))}
            </nav>
          </ScrollArea>

          <div className="border-t border-border/60 p-3 safe-bottom">
            <Button
              variant="ghost"
              className="w-full justify-start gap-2.5 text-[13px] text-destructive hover:bg-destructive/10 hover:text-destructive"
              onClick={() => { setOpen(false); onSignOut() }}
            >
              <LogOut className="size-4" aria-hidden="true" />
              Sign out
            </Button>
          </div>
        </SheetContent>
      </Sheet>
    </>
  )
}

