import { PageError } from '@/components/shared/PageError'

export default function AdminError({
  error,
  reset,
}: {
  error: Error & { digest?: string }
  reset: () => void
}) {
  return <PageError error={error} reset={reset} variant="full-page" routeContext="admin" />
