            name: metric.name,
            value: metric.value,
            rating: metric.rating,
          })
        }
      }

      onLCP(report)
      onINP(report)
      onCLS(report)
      onFCP(report)
      onTTFB(report)
    }

    void init()
  }, [])

  return null
}

