import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Suspense } from 'react'
import { Plus, Sparkles } from 'lucide-react'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import { Page, type PageAction } from '@/components/shared/Page'
import { EmptyState } from '@/components/shared/EmptyState'
import { Skeleton } from '@/components/ui/skeleton'
import { SubmissionsTable } from '@/components/consent/submissions/SubmissionsTable'
import { TemplatesGrid } from '@/components/consent/templates/TemplatesGrid'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'
import type { PageTab } from '@/components/shared/PageTabs'

export const metadata: Metadata = {
  title: 'Forms — InkOS',
}

// S24 Forms rebuild — Templates is the landing view (per Forms Scoping v1 spec).
// Submissions + Auto-send rules are secondary tabs. Rules is a placeholder tab
// in F1; real CRUD lands in F3 (consent_auto_send_rules migration + worker).
const VALID_TABS = ['templates', 'submissions', 'rules'] as const
type TabKey = (typeof VALID_TABS)[number]

interface SearchParams {
  tab?: string
}

function resolveTab(searchParams: SearchParams): TabKey {
  const requested = searchParams.tab as TabKey | undefined
  if (requested && VALID_TABS.includes(requested)) return requested
  return 'templates'
}

const FORM_TABS: PageTab[] = [
  {
    key: 'templates',
    label: 'Templates',
    href: '/forms?tab=templates',
    hidden: (role) => role === 'guest_artist',
  },
  {
    key: 'submissions',
    label: 'Submissions',
    href: '/forms?tab=submissions',
  },
  {
    key: 'rules',
    label: 'Auto-send rules',
    href: '/forms?tab=rules',
    hidden: (role) => role !== 'owner' && role !== 'admin',
  },
]

const TabSkeleton = () => (
  <div className="space-y-4">
    <Skeleton className="h-8 w-40" />
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
      {Array.from({ length: 6 }).map((_, i) => (
        <Skeleton key={i} className="h-40 w-full rounded-xl" />
      ))}
    </div>
  </div>
)

export default async function FormsPage({
  searchParams,
}: {
  searchParams: Promise<SearchParams>
}) {
  let activeStudio: Awaited<ReturnType<typeof getActiveStudio>>
  try {
    activeStudio = await getActiveStudio()
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  const { role, plan } = activeStudio
  const resolvedParams = await searchParams
  const activeTab = resolveTab(resolvedParams)

  const canManageTemplates = role === 'owner' || role === 'admin'

  // Primary action is tab-aware: + New template on Templates, nothing on
  // Submissions (Export all lives inside the table toolbar), + New rule
  // placeholder on Rules until F3 lands the real CRUD.
  const primaryAction: PageAction | undefined =
    activeTab === 'templates' && canManageTemplates
      ? { label: 'New template', href: '/forms/templates/new', icon: Plus }
      : undefined

  return (
    <Page
      title="Forms"
      subtitle="Consent, medical, photo release, and aftercare — all signed on client phones, stored forever."
      tabs={FORM_TABS}
      activeTab={activeTab}
      plan={plan as PlanTier}
      role={role as NavRole}
      {...(primaryAction ? { primaryAction } : {})}
    >
      {activeTab === 'templates' && (
        <Suspense fallback={<TabSkeleton />}>
          <TemplatesGrid />
        </Suspense>
      )}
      {activeTab === 'submissions' && (
        <Suspense fallback={<TabSkeleton />}>
          <SubmissionsTable />
        </Suspense>
      )}
      {activeTab === 'rules' && (
        <div className="py-12">
          <EmptyState
            icon={Sparkles}
            title="Auto-send rules are coming"
            description="Fire the right consent form at the right moment — on booking, for minors, after session completion, and more. Ships in the next Forms sprint."
            variant="coming-soon"
          />
        </div>
      )}
    </Page>
  )
}

'use client'

import { useRef } from 'react'
import { useRouter, usePathname } from 'next/navigation'
import { cn } from '@/lib/utils'
import { PlanBadge } from '@/components/shared/PlanBadge'
import { PLAN_ORDER } from '@/lib/billing/feature-gate'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'

export interface PageTab {
  key: string
  label: string
  href: string
  badge?: number | string
  gated?: PlanTier
  /** Return true to hide this tab for the given role */
  hidden?: (role: NavRole) => boolean
}

export interface PageTabsProps {
  tabs: PageTab[]
  activeKey: string
  currentPlan: PlanTier
  currentRole: NavRole
  className?: string
}

/**
 * S13 — Horizontal underline tab row with URL persistence via ?tab= query param.
 *
 * Accessibility:
 *  - role="tablist" on container
 *  - role="tab" + aria-selected on each trigger
 *  - Arrow key navigation within the tab row (ARIA authoring practices)
 *  - focus-visible ring on each trigger
 *
 * URL persistence:
 *  - Active tab read from ?tab= param by parent; defaulted to tabs[0].key if absent/invalid
 *  - Navigates via router.replace({pathname}?tab={key}, { scroll: false }) — no full reload
 *
 * Plan gating:
 *  - If tab.gated is set and user plan is below requirement, renders tab at reduced opacity
 *  - Click on gated tab routes to /settings/billing
 */
export function PageTabs({ tabs, activeKey, currentPlan, currentRole, className }: PageTabsProps) {
  const router = useRouter()
  const pathname = usePathname()
  const listRef = useRef<HTMLDivElement>(null)

  const visibleTabs = tabs.filter((t) => !(t.hidden?.(currentRole) ?? false))

  function isLocked(tab: PageTab): boolean {
    return tab.gated != null && PLAN_ORDER[currentPlan] < PLAN_ORDER[tab.gated]
  }

  function handleSelect(tab: PageTab) {
    if (isLocked(tab)) {
      router.push('/settings/billing')
      return
    }
    router.replace(`${pathname}?tab=${tab.key}`, { scroll: false })
  }

  function handleKeyDown(e: React.KeyboardEvent<HTMLButtonElement>, currentIndex: number) {
    const triggers = listRef.current?.querySelectorAll<HTMLButtonElement>('[role="tab"]')
    if (!triggers) return

    let nextIndex: number | null = null

    if (e.key === 'ArrowRight') {
      nextIndex = (currentIndex + 1) % triggers.length
    } else if (e.key === 'ArrowLeft') {
      nextIndex = (currentIndex - 1 + triggers.length) % triggers.length
    } else if (e.key === 'Home') {
      nextIndex = 0
    } else if (e.key === 'End') {
      nextIndex = triggers.length - 1
    }

    if (nextIndex !== null) {
      e.preventDefault()
      triggers[nextIndex]?.focus()
    }
  }

  return (
    <div
      ref={listRef}
      role="tablist"
      aria-label="Page sections"
      className={cn(
        'flex items-end gap-0 border-b border-border/60',
        'overflow-x-auto scrollbar-none',
        // Fade edges on mobile only
        '[mask-image:linear-gradient(to_right,transparent_0px,black_16px,black_calc(100%-16px),transparent_100%)]',
        'md:[mask-image:none]',
        className,
      )}
    >
      {visibleTabs.map((tab, index) => {
        const isActive = tab.key === activeKey
        const locked = isLocked(tab)

        return (
          <button
            key={tab.key}
            type="button"
            role="tab"
            aria-selected={isActive}
            onClick={() => handleSelect(tab)}
            onKeyDown={(e) => handleKeyDown(e, index)}
            className={cn(
              'relative flex items-center gap-1.5 px-3 h-10 shrink-0',
              'text-sm whitespace-nowrap transition-colors duration-150',
              'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-0',
              isActive
                ? [
                    'font-semibold text-foreground',
                    'after:absolute after:bottom-0 after:inset-x-0 after:h-0.5 after:bg-primary after:rounded-full',
                  ]
                : 'font-medium text-muted-foreground hover:text-foreground',
              locked && 'opacity-60 cursor-default',
            )}
          >
            {tab.label}
            {tab.gated != null && <PlanBadge plan={tab.gated} />}
            {tab.badge != null && (
              <span className="inline-flex items-center rounded-full bg-muted text-muted-foreground text-[10px] font-semibold leading-none px-1.5 py-0.5 min-w-[18px] justify-center tabular-nums">
                {tab.badge}
              </span>
            )}
          </button>
        )
      })}
    </div>
  )
}

'use client'

import Link from 'next/link'
import type { ReactNode } from 'react'
import type { LucideIcon } from 'lucide-react'
import { MoreHorizontal } from 'lucide-react'
import { PageShell } from './PageShell'
import { PageHeader } from './PageHeader'
import { PageTabs, type PageTab } from './PageTabs'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'

/**
 * S24 — Polaris-inspired `<Page>` composite.
 *
 * One entry point for every top-level authenticated route. Composes the
 * existing PageShell + PageHeader + PageTabs primitives with a typed
 * action API so every page shares the same rhythm:
 *
 *   Title + subtitle + metadata     [secondary actions] [primary action]
 *   Optional tab row (underline style)
 *   Children (content — the page owns its own rhythm below)
 *
 * Use `<Page>` for every standard route. Reach for the underlying primitives
 * directly only for exceptional layouts (dashboard hero, onboarding chrome).
 */

export interface PageAction {
  /** Button label. Required. */
  label: string
  /** Optional click handler for state-based actions (open drawer, etc.). */
  onClick?: () => void
  /** Optional href for nav-based actions. Mutually exclusive with onClick. */
  href?: string
  /** Optional leading icon. */
  icon?: LucideIcon
  /** Loading state — disables the button and swaps the label for a spinner. */
  loading?: boolean
  /** Disabled state. */
  disabled?: boolean
  /** Use the destructive variant (red) instead of default/secondary. */
  destructive?: boolean
}

export interface PageProps {
  /** Page title — rendered in Instrument Serif per brand. */
  title: string
  /** Short description under the title. */
  subtitle?: string
  /**
   * Chips/badges rendered inline to the right of the title (status badges,
   * LIVE pills, plan badges). Kept small so they don't break the H1 rhythm.
   */
  titleMetadata?: ReactNode
  /** Back link rendered above the title (usually on detail pages). */
  backAction?: { href: string; label?: string }
  /** Primary call-to-action — Onyx fill, top-right. Max one per page. */
  primaryAction?: PageAction
  /**
   * Secondary actions — outline buttons left of the primary action. First two
   * render inline; the rest collapse into an overflow "..." dropdown so the
   * header never exceeds a single row.
   */
  secondaryActions?: PageAction[]
  /** Tab row below the header. */
  tabs?: PageTab[]
  /** Active tab key — required when `tabs` is provided. */
  activeTab?: string
  /** Current plan — required for tab plan-gating. Defaults to 'solo'. */
  plan?: PlanTier
  /** Current role — required for tab role-filtering. Defaults to 'owner'. */
  role?: NavRole
  /** Pass-through to PageShell for calendar / messages style full-height layouts. */
  fullHeight?: boolean
  /**
   * Narrow the content width for forms / settings pages. `720` → 720px,
   * `960` → 960px, `false` / undefined → default 1440px cap.
   */
  narrowWidth?: 720 | 960 | false
  /** Extra classes applied to the outer PageShell. */
  className?: string
  /** Page content. */
  children: ReactNode
}

function ActionButton({
  action,
  primary = false,
}: {
  action: PageAction
  primary?: boolean
}) {
  const Icon = action.icon
  const variant = action.destructive
    ? 'destructive'
    : primary
    ? 'default'
    : 'outline'

  const content = (
    <>
      {Icon && <Icon className="h-3.5 w-3.5" aria-hidden="true" />}
      {action.label}
    </>
  )

  if (action.href) {
    return (
      <Button
        variant={variant}
        size="sm"
        loading={action.loading ?? false}
        disabled={action.disabled ?? false}
        render={<Link href={action.href} />}
      >
        {content}
      </Button>
    )
  }

  return (
    <Button
      variant={variant}
      size="sm"
      loading={action.loading ?? false}
      disabled={action.disabled ?? false}
      onClick={action.onClick}
    >
      {content}
    </Button>
  )
}

function SecondaryActionsRow({ actions }: { actions: PageAction[] }) {
  if (actions.length === 0) return null

  // First two render inline; the rest collapse into an overflow menu so the
  // header stays single-row even on pages with many secondary tools.
  const inline = actions.slice(0, 2)
  const overflow = actions.slice(2)

  return (
    <>
      {inline.map((action) => (
        <ActionButton key={action.label} action={action} />
      ))}
      {overflow.length > 0 && (
        <DropdownMenu>
          <DropdownMenuTrigger
            render={
              <Button variant="outline" size="sm" className="h-9 w-9 p-0" aria-label="More actions">
                <MoreHorizontal className="h-4 w-4" aria-hidden="true" />
              </Button>
            }
          />
          <DropdownMenuContent align="end">
            {overflow.map((action) => {
              const Icon = action.icon
              if (action.href) {
                return (
                  <DropdownMenuItem
                    key={action.label}
                    className="gap-2 text-xs"
                    disabled={action.disabled ?? false}
                    render={<Link href={action.href} />}
                  >
                    {Icon && <Icon className="h-3.5 w-3.5" aria-hidden="true" />}
                    {action.label}
                  </DropdownMenuItem>
                )
              }
              return (
                <DropdownMenuItem
                  key={action.label}
                  className={action.destructive ? 'gap-2 text-xs text-destructive focus:text-destructive' : 'gap-2 text-xs'}
                  disabled={action.disabled ?? false}
                  onClick={action.onClick}
                >
                  {Icon && <Icon className="h-3.5 w-3.5" aria-hidden="true" />}
                  {action.label}
                </DropdownMenuItem>
              )
            })}
          </DropdownMenuContent>
        </DropdownMenu>
      )}
    </>
  )
}

export function Page({
  title,
  subtitle,
  titleMetadata,
  backAction,
  primaryAction,
  secondaryActions = [],
  tabs,
  activeTab,
  plan = 'solo',
  role = 'owner',
  fullHeight = false,
  narrowWidth,
  className,
  children,
}: PageProps) {
  const maxWidth = narrowWidth === false ? false : narrowWidth ?? 1440
  const hasActions = primaryAction != null || secondaryActions.length > 0

  // Build the header `actions` slot from the typed action arrays.
  const actionsNode = hasActions ? (
    <>
      <SecondaryActionsRow actions={secondaryActions} />
      {primaryAction && <ActionButton action={primaryAction} primary />}
    </>
  ) : undefined

  // Build the title node with optional metadata chips to the right.
  const titleNode = titleMetadata ? (
    <div className="flex items-center gap-3 min-w-0">
      <span className="min-w-0 truncate">{title}</span>
      <span className="flex items-center gap-1.5 shrink-0">{titleMetadata}</span>
    </div>
  ) : (
    title
  )

  return (
    <PageShell
      fullHeight={fullHeight}
      maxWidth={maxWidth}
      {...(className ? { className } : {})}
    >
      {/* When titleMetadata is present we need a ReactNode instead of string; the
          PageHeader today expects a string title, so render chips INSIDE the
          existing description slot as a row above for that edge case. Simpler
          path: always pass `title` as string and stamp the metadata via an
          absolutely-positioned slot. For now we pass the string title. */}
      <PageHeader
        title={typeof titleNode === 'string' ? titleNode : title}
        {...(subtitle ? { description: subtitle } : {})}
        {...(actionsNode ? { actions: actionsNode } : {})}
        {...(backAction ? { backHref: backAction.href } : {})}
      />

      {/* Metadata chips rendered just under the title — preserves the existing
          PageHeader contract while giving us Polaris-style titleMetadata. */}
      {titleMetadata && (
        <div className="-mt-4 flex items-center gap-1.5">{titleMetadata}</div>
      )}

      {tabs && tabs.length > 0 && activeTab && (
        <PageTabs tabs={tabs} activeKey={activeTab} currentPlan={plan} currentRole={role} />
      )}

      {children}
    </PageShell>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Suspense } from 'react'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { PageTabs } from '@/components/shared/PageTabs'
import { PageViews } from '@/components/shared/PageViews'
import { filterTabsForRole } from '@/components/shared/page-tabs-utils'
import { AppointmentsPageClient } from './_components/AppointmentsPageClient'
import { WaitlistPageClient } from '../waitlist/_components/WaitlistPageClient'
import type { PageTab } from '@/components/shared/PageTabs'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'
import { PageShell } from '@/components/shared/PageShell'
import { PageHeader } from '@/components/shared/PageHeader'
import { Button } from '@/components/ui/button'
import Link from 'next/link'
import { Plus } from 'lucide-react'

export const metadata: Metadata = {
  title: 'Appointments — InkOS',
}

const APPOINTMENTS_TABS: PageTab[] = [
  {
    key: 'list',
    label: 'All',
    href: '/appointments?tab=list',
  },
  {
    key: 'today',
    label: 'Today',
    href: '/appointments?tab=today',
  },
  {
    key: 'waitlist',
    label: 'Waitlist',
    href: '/appointments?tab=waitlist',
    hidden: (role) =>
      role !== 'owner' && role !== 'admin' && role !== 'receptionist',
  },
]

const VALID_KEYS = new Set(APPOINTMENTS_TABS.map((t) => t.key))

interface Props {
  searchParams: Promise<Record<string, string | string[] | undefined>>
}

export default async function AppointmentsPage({ searchParams }: Props) {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()
  let plan: PlanTier = 'solo'
  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', auth.studioId)
    .eq('status', 'active')
    .maybeSingle()
  if (sub?.plan_tier) plan = sub.plan_tier as PlanTier

  const role = auth.role as NavRole
  const params = await searchParams
  const rawTab = typeof params.tab === 'string' ? params.tab : undefined
  const activeKey = rawTab && VALID_KEYS.has(rawTab) ? rawTab : 'list'

  return (
    <PageShell>
      <PageHeader
        title="Appointments"
        description="Manage all studio bookings"
        actions={
          <Button size="sm" render={<Link href="/appointments/new" />}>
            <Plus className="h-4 w-4" />
            New booking
          </Button>
        }
      />

      <PageViews>
        <PageTabs
          tabs={filterTabsForRole(APPOINTMENTS_TABS, role)}
          activeKey={activeKey}
          currentPlan={plan}
          currentRole={role}
        />
      </PageViews>

      <div role="tabpanel" id={`tabpanel-${activeKey}`} className="flex flex-col flex-1 min-h-0">
        <Suspense fallback={<div className="flex-1 animate-pulse bg-muted/20 rounded-xl min-h-[200px]" />}>
          {activeKey === 'list' && <AppointmentsPageClient />}
          {activeKey === 'today' && <AppointmentsPageClient forceToday />}
          {activeKey === 'waitlist' && <WaitlistPageClient />}
        </Suspense>
      </div>
    </PageShell>
  )
}

