export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import type { ClientHealthSummaryRow } from '@/lib/clients/health-types'
import {
  CLIENT_LIST_PAGE_SIZE,
  CLIENT_LIST_SELECT,
  CLIENT_LIST_SORT_KEYS,
  CLIENT_LIST_SPENDING_TIERS,
  getClientListLastVisitConstraint,
  getClientListSortOrders,
  getClientListSpendingBounds,
} from '@/lib/clients/list-query'
import { logger } from '@/lib/logger'
import { rawQuery } from '@/lib/supabase/raw-query'

// Parse query-string booleans safely. z.coerce.boolean() is broken for URL
// params because JavaScript Boolean("false") === true. Accept only the
// canonical strings "true"/"false"; everything else (empty, missing) → undefined.
const queryBool = z
  .enum(['true', 'false'])
  .optional()
  .transform((v) => (v === undefined ? undefined : v === 'true'))

const CLIENT_LIST_LAST_VISIT_QUERY_RANGES = [
  '7d',
  '30d',
  '90d',
  '90d+',
  'never',
  'all',
] as const

const ClientListSchema = z.object({
  q: z.string().max(200).optional(),
  tags: z.string().optional(), // comma-separated tag names
  vip: queryBool,
  inactive: queryBool,
  no_show: queryBool,
  has_alerts: queryBool,
  spending: z.enum(CLIENT_LIST_SPENDING_TIERS).optional(),
  spending_min: z.coerce.number().int().min(0).optional(),
  spending_max: z.coerce.number().int().min(0).optional(),
  // Accept 'true' | 'false' | 'any'. Default to excluding archived.
  // 'any' returns archived + non-archived together.
  archived: z.enum(['true', 'false', 'any']).default('false'),
  page: z.coerce.number().int().min(1).default(1),
  per_page: z.coerce.number().int().min(1).max(100).default(CLIENT_LIST_PAGE_SIZE),
  sort: z.enum(CLIENT_LIST_SORT_KEYS).default('last_visit_desc'),
  // Sprint 6 filter facets (B2 blocker fix)
  artist_ids: z.string().optional(), // comma-separated artist UUIDs
  service_ids: z.string().optional(), // comma-separated service UUIDs
  last_visit_from: z.string().optional(), // ISO date string
  last_visit_to: z.string().optional(), // ISO date string
  // Supports canonical values plus legacy saved-view values without migration.
  last_visit_range: z.enum(CLIENT_LIST_LAST_VISIT_QUERY_RANGES).optional(),
})

const HANDLE_REGEX = /^[^@/]{1,100}$/
// Accept both the drawer's {line1, line2, zip} shape and the legacy
// {street, postal_code} shape — the DB column is JSON so we store whichever
// the caller sent. Silently dropping line1/zip was causing full-address
// data-loss on create.
const AddressSchema = z
  .object({
    line1: z.string().optional(),
    line2: z.string().optional(),
    street: z.string().optional(),
    city: z.string().optional(),
    state: z.string().optional(),
    zip: z.string().optional(),
    postal_code: z.string().optional(),
    country: z.string().optional(),
  })
  .optional()
  .nullable()

const CreateClientSchema = z.object({
  first_name: z.string().min(1, 'First name is required').max(100),
  last_name: z.string().max(100).optional().nullable(),
  email: z
    .string()
    .email('Enter a valid email address')
    .optional()
    .nullable()
    .or(z.literal('').transform(() => null)),
  phone: z
    .string()
    .regex(/^[+\d][\d\s\-().]{5,20}$/, 'Enter a valid phone number')
    .optional()
    .nullable()
    .or(z.literal('').transform(() => null)),
  date_of_birth: z.string().optional().nullable(),
  address: AddressSchema,
  source: z.string().optional().nullable(),
  referral_source: z.string().optional().nullable(),
  tags: z.array(z.string()).max(10, 'Maximum 10 tags per client').default([]),
  preferred_contact: z.enum(['email', 'sms', 'phone', 'whatsapp']).default('email'),
  consent_minor: z.boolean().default(false),
  // Consent prefs
  marketing_email: z.boolean().default(false),
  marketing_sms: z.boolean().default(false),
  // S18 social fields — previously silently stripped from POST
  instagram_handle: z.string().regex(HANDLE_REGEX).optional().nullable(),
  tiktok_handle: z.string().regex(HANDLE_REGEX).optional().nullable(),
  website_url: z.string().url().optional().nullable(),
  notes: z.string().optional().nullable(),
  // S23a additions — pronouns + avatar + allergies (allergies feed client_notes)
  pronouns: z.string().max(60).optional().nullable(),
  avatar_url: z.string().url('Avatar must be a valid URL').optional().nullable(),
  allergies: z.string().max(1000).optional().nullable(),
})

export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { searchParams } = new URL(request.url)
  const parsed = ClientListSchema.safeParse(Object.fromEntries(searchParams))
  if (!parsed.success) {
    return NextResponse.json(
      { error: 'Invalid clients query', details: parsed.error.flatten() },
      { status: 400 },
    )
  }

  const {
    q, tags, vip, inactive, no_show, has_alerts, spending, spending_min, spending_max,
    archived, page, per_page, sort,
    artist_ids, service_ids, last_visit_range,
  } = parsed.data

  let last_visit_from = parsed.data.last_visit_from
  let last_visit_to = parsed.data.last_visit_to
  if (last_visit_range && !last_visit_from && !last_visit_to) {
    const constraint = getClientListLastVisitConstraint(last_visit_range)
    if (constraint?.kind === 'between') {
      last_visit_from = constraint.from
      last_visit_to = constraint.to
    }
  }

  try {
    const supabase = await createClient()
    let tagLibrary: { id: string; name: string }[] | null = null
    let filteredClientIds: string[] = []
    let hasFilteredClientIds = false

    const mergeFilteredClientIds = (nextIds: string[]) => {
      const uniqueNextIds = [...new Set(nextIds)]
      if (!hasFilteredClientIds) {
        filteredClientIds = uniqueNextIds
        hasFilteredClientIds = true
        return
      }
      const nextIdSet = new Set(uniqueNextIds)
      filteredClientIds = filteredClientIds.filter((id) => nextIdSet.has(id))
    }

    const getTagLibrary = async () => {
      if (tagLibrary) return tagLibrary
      const { data, error } = await supabase
        .from('client_tags')
        .select('id, name')
        .eq('studio_id', authUser.studioId)

      if (error) throw error
      tagLibrary = data ?? []
      return tagLibrary
    }

    const resolveCanonicalTagNames = async (rawTokens: string[]) => {
      const library = await getTagLibrary()
      return [...new Set(rawTokens.map((token) => {
        const match = library.find((tag) => tag.id === token || tag.name === token)
        return match?.name ?? token
      }))]
    }

    let query = supabase
      .from('clients')
      .select(CLIENT_LIST_SELECT, { count: 'exact' })
      .eq('studio_id', authUser.studioId)

    // Archive filter: 'true' → archived only; 'false' → active only; 'any' → no filter
    if (archived === 'true') {
      query = query.not('archived_at', 'is', null)
    } else if (archived === 'false') {
      query = query.is('archived_at', null)
    }

    // Full-text search — use search_vector (Sprint 6 pg_trgm index) for fuzzy match
    // Falls back to the pre-existing fts column shape but targets the new GIN-indexed column
    if (q) {
      query = query.textSearch('search_vector', q, { type: 'websearch' })
    }

    // Tag filter (clients must have ALL specified tags). Accept legacy saved
    // views that still store tag IDs by resolving them back to canonical names.
    if (tags) {
      const tagTokens = tags.split(',').filter(Boolean)
      if (tagTokens.length > 0) {
        const tagNames = await resolveCanonicalTagNames(tagTokens)
        query = query.contains('tags', tagNames)
      }
    }

    // VIP filter — resolve the exact stored tag name when the studio has one.
    if (vip) {
      const library = await getTagLibrary()
      const vipTagName = library.find((tag) => tag.name.toLowerCase() === 'vip')?.name ?? 'vip'
      query = query.contains('tags', [vipTagName])
    }

    // Inactive filter — last_visit_at < 90 days ago OR null
    if (inactive) {
      const ninetyDaysAgo = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString()
      query = query.or(`last_visit_at.lt.${ninetyDaysAgo},last_visit_at.is.null`)
    }

    // No-show filter
    if (no_show) {
      query = query.gt('no_show_count', 0)
    }

    // Spending range filter (in cents). Explicit min/max overrides the
    // canonical tier translation for backward compatibility.
    if (spending_min !== undefined || spending_max !== undefined) {
      if (spending_min !== undefined) {
        query = query.gte('total_spent_cents', spending_min)
      }
      if (spending_max !== undefined) {
        query = query.lte('total_spent_cents', spending_max)
      }
    } else if (spending) {
      const bounds = getClientListSpendingBounds(spending)
      if (bounds.minInclusive !== undefined) {
        query = query.gte('total_spent_cents', bounds.minInclusive)
      }
      if (bounds.minExclusive !== undefined) {
        query = query.gt('total_spent_cents', bounds.minExclusive)
      }
      if (bounds.maxInclusive !== undefined) {
        query = query.lte('total_spent_cents', bounds.maxInclusive)
      }

