'use client'

import { useQuery } from '@tanstack/react-query'
import { Package, AlertTriangle } from 'lucide-react'
import { KpiCard } from '@/components/shared/KpiCard'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { TableSkeleton } from '@/components/skeletons'
import { formatCurrency } from '@/lib/utils'

interface CategoryStat {
  name: string
  count: number
  totalValue: number
}

interface InventoryData {
  kpis: {
    totalItems: number
    lowStockCount: number
    totalCogsConsumed: number
  }
  categoryBreakdown: CategoryStat[]
}

export function InventoryReportClient() {
  const { data, isLoading, error } = useQuery<InventoryData>({
    queryKey: ['reports', 'inventory'],
    queryFn: () => fetch('/api/reports/inventory').then((r) => r.json()),
    staleTime: 5 * 60 * 1000,
  })

  return (
    <DataState
      data={data}
      isLoading={isLoading}
      isError={!!error}
      error={error instanceof Error ? error : null}
      loadingSlot={<TableSkeleton rows={3} />}
      emptySlot={
        <EmptyState
          icon={Package}
          title="No inventory data yet"
          description="Add inventory items to start tracking COGS and category breakdown."
          variant="default"
        />
      }
    >
      {(d) => (
        <div className="space-y-6">
          {/* KPIs */}
          <div className="grid gap-4 sm:grid-cols-3">
            <KpiCard label="Total Items" value={d.kpis.totalItems} subtextLabel="in inventory" icon={Package} index={0} />
            <KpiCard
              label="Low Stock"
              value={d.kpis.lowStockCount}
              subtextLabel="items below threshold"
              icon={AlertTriangle}
              invertTrend
              trend={d.kpis.lowStockCount > 0 ? 'up' : 'neutral'}
              index={1}
            />
            <KpiCard
              label="COGS Consumed"
              value={formatCurrency(d.kpis.totalCogsConsumed)}
              subtextLabel="cost of goods used"
              icon={Package}
              index={2}
            />
          </div>

          {/* Category breakdown */}
          {d.categoryBreakdown.length === 0 ? (
            <EmptyState
              icon={Package}
              title="No category data"
              description="Add inventory items to see category breakdown."
            />
          ) : (
            <Card className="border-border/50 shadow-[var(--shadow-card)]">
              <CardHeader>
                <CardTitle className="text-sm font-medium">Inventory by Category</CardTitle>
              </CardHeader>
              <CardContent className="p-0">
                <div className="divide-y divide-border/50">
                  {d.categoryBreakdown
                    .sort((a, b) => b.totalValue - a.totalValue)
                    .map((cat) => (
                      <div key={cat.name} className="flex items-center gap-4 px-6 py-4">
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-medium truncate">{cat.name}</p>
                          <p className="text-xs text-muted-foreground">{cat.count} items</p>
                        </div>
                        <div className="text-right shrink-0">
                          <p className="text-sm font-semibold tabular-nums">{formatCurrency(cat.totalValue)}</p>
                          <p className="text-xs text-muted-foreground">stock value</p>
                        </div>
                        <Badge variant={cat.count < 3 ? 'destructive' : 'secondary'} className="shrink-0">
                          {cat.count}
                        </Badge>
                      </div>
                    ))}
                </div>
              </CardContent>
            </Card>
          )}
        </div>
      )}
    </DataState>
  )
}

import type { NextRequest } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { z } from 'zod'

const querySchema = z.object({
  from: z.string().datetime({ offset: true }).optional(),
  to: z.string().datetime({ offset: true }).optional(),
})

export async function GET(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return new Response('Unauthorized', { status: 401 })
  if (!['owner', 'admin'].includes(auth.role)) return new Response('Forbidden', { status: 403 })

  const parsed = querySchema.safeParse(Object.fromEntries(req.nextUrl.searchParams))
  if (!parsed.success) return Response.json({ error: parsed.error.flatten() }, { status: 400 })

  const { from, to } = parsed.data
  const supabase = await createClient()

  try {
    const [itemsResult, movementsResult] = await Promise.all([
      supabase
        .from('inventory_items')
        .select('id, name, category, current_stock, min_threshold, cost_per_unit_cents, supplier_id')
        .eq('studio_id', auth.studioId),
      supabase
        .from('inventory_movements')
        .select('item_id, qty_delta, reason, created_at, inventory_items(name, cost_per_unit_cents)')
        .eq('studio_id', auth.studioId)
        .lt('qty_delta', 0) // only consumption
        .order('created_at', { ascending: false })
        .then((r) => {
          if (from && r.data) r.data = r.data.filter((m) => m.created_at >= (from ?? ''))
          if (to && r.data) r.data = r.data.filter((m) => m.created_at <= (to ?? ''))
          return r
        }),
    ])

    if (itemsResult.error) throw itemsResult.error
    if (movementsResult.error) throw movementsResult.error

    const items = itemsResult.data ?? []
    const movements = movementsResult.data ?? []

    const lowStockCount = items.filter((i) => i.current_stock <= i.min_threshold).length
    const totalCogsConsumed = movements.reduce((sum, m) => {
      const item = m.inventory_items
      const cost = Array.isArray(item) ? (item[0]?.cost_per_unit_cents ?? 0) : ((item as { cost_per_unit_cents?: number } | null)?.cost_per_unit_cents ?? 0)
      return sum + Math.abs(m.qty_delta) * cost
    }, 0)

    // Category breakdown
    const categoryBreakdown = items.reduce<Record<string, { count: number; totalValue: number }>>((acc, i) => {
      const cat = i.category ?? 'Uncategorized'
      if (!acc[cat]) acc[cat] = { count: 0, totalValue: 0 }
      acc[cat].count++
      acc[cat].totalValue += i.current_stock * i.cost_per_unit_cents
      return acc
    }, {})

    return Response.json({
      kpis: {
        totalItems: items.length,
        lowStockCount,
        totalCogsConsumed,
      },
      categoryBreakdown: Object.entries(categoryBreakdown).map(([name, d]) => ({ name, ...d })),
    })
  } catch (err) {
    logger.error({ err, studioId: auth.studioId }, 'inventory report failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

'use client'

import type { ReactNode } from 'react'
import { Inbox, Loader2 } from 'lucide-react'
import { EmptyState } from './EmptyState'
import { PageError } from './PageError'
import { useLoadingTimeout } from '@/lib/hooks/use-loading-timeout'

interface DataStateProps<T> {
  data: T | null | undefined
  isLoading?: boolean
  isError?: boolean
  error?: Error | null
  isEmpty?: boolean
  children: (data: NonNullable<T>) => ReactNode
  loadingSlot?: ReactNode
  emptySlot?: ReactNode
  errorSlot?: ReactNode
}

function computeIsEmpty<T>(data: T | null | undefined, override?: boolean): boolean {
  if (override !== undefined) return override
  if (data == null) return true
  if (Array.isArray(data)) return data.length === 0
  return false
}

export function DataState<T>({
  data,
  isLoading = false,
  isError = false,
  error,
  isEmpty: isEmptyOverride,
  children,
  loadingSlot,
  emptySlot,
  errorSlot,
}: DataStateProps<T>) {
  const { showConnectionHint, showSlowHint } = useLoadingTimeout(isLoading)

  if (isError) {
    return (
      <>
        {errorSlot ?? (
          <PageError
            error={error ?? new Error('An error occurred')}
            reset={() => undefined}
            variant="inline"
          />
        )}
      </>
    )
  }

  if (isLoading) {
    const defaultSpinner = (
      <div
        role="status"
        className="flex flex-col items-center justify-center py-12"
        aria-busy="true"
        aria-label="Loading"
      >
        <Loader2 aria-hidden="true" className="h-5 w-5 animate-spin text-muted-foreground" />
        {showConnectionHint && !showSlowHint && (
          <p className="mt-3 text-center text-xs text-muted-foreground">
            Still loading — check your connection?
          </p>
        )}
        {showSlowHint && (
          <p className="mt-3 text-center text-xs text-muted-foreground">
            This is taking longer than expected.{' '}
            <button
              type="button"
              onClick={() => window.location.reload()}
              className="underline underline-offset-2 hover:text-foreground transition-colors"
            >
              Retry
            </button>
          </p>
        )}
      </div>
    )

    return <>{loadingSlot ?? defaultSpinner}</>
  }

  const isEmpty = computeIsEmpty(data, isEmptyOverride)

  if (isEmpty) {
    return (
      <>
        {emptySlot ?? (
          <EmptyState
            icon={Inbox}
            title="Nothing here yet"
            size="md"
            variant="default"
          />
        )}
      </>
    )
  }

  return <>{children(data as NonNullable<T>)}</>
}

