'use client'

import { useQuery } from '@tanstack/react-query'
import { Wand2, DollarSign, Star } from 'lucide-react'
import { KpiCard } from '@/components/shared/KpiCard'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Skeleton } from '@/components/ui/skeleton'
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { ChartSkeleton } from '@/components/skeletons'
import { formatCurrency } from '@/lib/utils'
import dynamic from 'next/dynamic'

const RechartsBarChart = dynamic(() => import('./RechartsBarChart'), {
  ssr: false,
  loading: () => <Skeleton className="h-56 w-full" />,
})

interface ModelStat {
  model: string
  count: number
  cost: number
}

interface MonthlyPoint {
  month: string
  count: number
  cost: number
}

interface AiUsageData {
  kpis: {
    total: number
    totalCost: number
    totalTokens: number
    avgRating: number | null
  }
  modelBreakdown: ModelStat[]
  monthlyTrend: MonthlyPoint[]
}

export function AiUsageReportClient() {
  const { data, isLoading, error } = useQuery<AiUsageData>({
    queryKey: ['reports', 'ai'],
    queryFn: () => fetch('/api/reports/ai').then((r) => r.json()),
    staleTime: 5 * 60 * 1000,
  })

  return (
    <DataState
      data={data}
      isLoading={isLoading}
      isError={!!error}
      error={error instanceof Error ? error : null}
      loadingSlot={<ChartSkeleton />}
      isEmpty={data?.kpis.total === 0}
      emptySlot={
        <EmptyState
          icon={Wand2}
          title="No AI generations yet"
          description="AI design generations will appear here once clients start using the feature."
          variant="default"
        />
      }
    >
      {(d) => {
        const trendForChart = d.monthlyTrend.map((p) => ({
          name: p.month,
          value: Math.round(p.cost / 100),
        }))

        return (
          <div className="space-y-6">
            {/* KPIs */}
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
              <KpiCard label="Generations" value={d.kpis.total} subtextLabel="total AI calls" icon={Wand2} index={0} />
              <KpiCard
                label="Total Cost"
                value={formatCurrency(d.kpis.totalCost)}
                subtextLabel="charged to studio"
                icon={DollarSign}
                index={1}
              />
              <KpiCard
                label="Tokens Used"
                value={d.kpis.totalTokens.toLocaleString()}
                subtextLabel="input + output"
                icon={Wand2}
                index={2}
              />
              <KpiCard
                label="Avg Rating"
                value={d.kpis.avgRating != null ? `${d.kpis.avgRating.toFixed(1)} / 5` : 'No ratings'}
                subtextLabel="user satisfaction"
                icon={Star}
                trend={d.kpis.avgRating != null && d.kpis.avgRating >= 4 ? 'up' : 'neutral'}
                index={3}
              />
            </div>

            {/* Monthly cost trend */}
            {trendForChart.length > 0 && (
              <Card className="border-border/50 shadow-[var(--shadow-card)]">
                <CardHeader>
                  <CardTitle className="text-sm font-medium">Monthly AI Cost ($)</CardTitle>
                </CardHeader>
                <CardContent>
                  <RechartsBarChart
                    data={trendForChart}
                    dataKey="value"
                    label="Cost ($)"
                    formatValue={(v) => `$${v}`}
                  />
                </CardContent>
              </Card>
            )}

            {/* Model breakdown */}
            {d.modelBreakdown.length > 0 && (
              <Card className="border-border/50 shadow-[var(--shadow-card)]">
                <CardHeader>
                  <CardTitle className="text-sm font-medium">Model Breakdown</CardTitle>
                </CardHeader>
                <CardContent className="p-0">
                  <div className="divide-y divide-border/50">
                    {d.modelBreakdown
                      .sort((a, b) => b.cost - a.cost)
                      .map((m) => (
                        <div key={m.model} className="flex items-center gap-4 px-6 py-4">
                          <div className="flex-1 min-w-0">
                            <p className="text-sm font-medium font-mono truncate">{m.model}</p>
                            <p className="text-xs text-muted-foreground">{m.count} generations</p>
                          </div>
                          <div className="text-right shrink-0">
                            <p className="text-sm font-semibold tabular-nums">{formatCurrency(m.cost)}</p>
                            <p className="text-xs text-muted-foreground">total cost</p>
                          </div>
                          <Badge variant="secondary" className="shrink-0 font-mono">
                            {Math.round(m.cost / Math.max(m.count, 1))}¢ avg
                          </Badge>
                        </div>
                      ))}
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        )
      }}
    </DataState>
  )
}

